from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        parents = {}
        self._collect_parent_map(self, None, parents)
        target = self._find(self, from_node)
        if target is None:
            raise ValueError("Tree could not be reoriented")
        return self._rebuild(target, None, parents)

    def path_to(self, from_node, to_node):
        reoriented = self.from_pov(from_node)
        path = self._path(reoriented, to_node)
        if path is None:
            raise ValueError("No path found")
        return path

    def _collect_parent_map(self, node, parent, parents):
        parents[id(node)] = parent
        for child in node.children:
            self._collect_parent_map(child, node, parents)

    def _find(self, node, label):
        if node.label == label:
            return node
        for child in node.children:
            found = self._find(child, label)
            if found is not None:
                return found
        return None

    def _rebuild(self, node, came_from, parents):
        children = []
        for child in node.children:
            if child is came_from:
                continue
            children.append(self._rebuild(child, node, parents))
        parent = parents.get(id(node))
        if parent is not None and parent is not came_from:
            children.append(self._rebuild(parent, node, parents))
        return Tree(node.label, children)

    def _path(self, node, target):
        if node.label == target:
            return [node.label]
        for child in node.children:
            sub = self._path(child, target)
            if sub is not None:
                return [node.label] + sub
        return None

